<?php $entityLabel=['books'=>'Account books','businesses'=>'Businesses & personal','categories'=>'Categories','people'=>'People'][$entity]; ?>
<div class="page-heading"><div><span class="eyebrow"><?= e(t($entityLabel)) ?></span><h1><?= e(t($title)) ?></h1></div><a class="button" href="<?= url('manage/' . $entity) ?>"><?= e(t('Back to list')) ?></a></div>
